WORKSHOP_TARGETS = {"台南": 25, "台中": 20, "台北": 50}


def _countdown_days(date_str: str) -> int:
    target = datetime.strptime(date_str, "%Y-%m-%d").date()
    return (target - date.today()).days


def _logged_in() -> bool:
    return bool(session.get("logged_in"))


