        db.set_paid(conn, reg_id, paid, paid_method, amount)
    conn.close()
    return redirect(url_for("admin", workshop=workshop))


@app.route("/admin/delete/<int:reg_id>", methods=["POST"])
def delete(reg_id):
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))
